 breadcrumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Accueil','item':SITE_URL},{'@type':'ListItem','position':2,'name':page_title.split('|')[0].strip(),'item':canon}]} if filename!='index.html' else None
 ld=[schema]+([breadcrumb] if breadcrumb else [])+([jsonld] if jsonld else [])
 social=urljoin(SITE_URL,og_img)
 doc=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#050e30"><meta name="description" content="{e(desc)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{canon}"><meta property="og:locale" content="fr_FR"><meta property="og:site_name" content="G-INNOVA"><meta property="og:type" content="website"><meta property="og:title" content="{e(page_title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{canon}"><meta property="og:image" content="{social}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(page_title)}"><meta name="twitter:description" content="{e(desc)}"><meta name="twitter:image" content="{social}"><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="css/style.css"><script src="js/main.js" defer></script><title>{e(page_title)}</title><script type="application/ld+json">{json.dumps(ld,ensure_ascii=False).replace('</','<\\/')}</script></head><body>{header(active)}<main id="contenu">{body}</main>{footer()}</body></html>'''
 (ROOT/filename).write_text(doc,encoding='utf-8')

