 # Open Graph custom artwork; untouched original logo and portraits remain separately included.
 im=Image.new('RGB',(1200,630),'#061133');d=ImageDraw.Draw(im)
 for x in range(1200):
  r=int(5+min(1,x/1200)*10);g=int(15+min(1,x/1200)*19);b=int(45+min(1,x/1200)*60)
  d.line([(x,0),(x,630)],fill=(r,g,b))
 for radius in range(260,0,-2):
  c=(max(10,50-radius//10),max(25,83-radius//14),max(100,255-radius//5))
  d.ellipse((840-radius,315-radius,840+radius,315+radius),outline=c,width=3)
 fonts=['/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf','/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf']
 f=next((i for i in fonts if Path(i).exists()),None)
 f1=ImageFont.truetype(f,88) if f else ImageFont.load_default();f2=ImageFont.truetype(f,36) if f else ImageFont.load_default();f3=ImageFont.truetype(f,23) if f else ImageFont.load_default()
 d.text((72,160),'G-INNOVA',font=f1,fill='white');d.text((77,280),'Services · Digital · IA',font=f2,fill='#a4b8ff');d.text((77,365),SLOGAN,font=f3,fill='#ffdb91')
